import Base
type Cell is Data:
  Leaf{value: Nat}
  Nest{cell: Cell}
type Tag is Data:
  C{cell: Cell, mark: Bool}
  D{cell: Cell, mark: Bool}
  E{cell: Cell, mark: Bool}
type Choice is Data:
  X{flag: Bool}
  Y{flag: Bool}
def matrix(tag: Tag, choice: Choice) -> Nat:
  match tag choice:
    case _ X{True{}}:
      33n
    case C{Nest{Leaf{value}}, True{}} X{True{}}:
      11n
    case D{Nest{Leaf{value}}, True{}} X{True{}}:
      22n
    case _ _:
      44n

